function fail(m){throw new Error(m)}
function sha(bytes){return crypto.createHash('sha256').update(bytes).digest('hex')}
function shaFile(file){return sha(fs.readFileSync(file))}
function regular(file){const s=fs.lstatSync(file);return s.isFile()&&!s.isSymbolicLink()}
function count(s,n){return s.split(n).length-1}
function replaceOnce(s,a,b,label){const n=count(s,a);if(n!==1)fail('patch_anchor_mismatch:'+label+':'+n);return s.replace(a,b)}
function patchBase(s){
  const a="  host_action_v2_installer_v1: { operation: 'host_action.host_action_v2_installer_v1', rollback: 'host-action-v2:host-action-v2-installer-v1:four-file-restore' }\n});";
  const b="  host_action_v2_installer_v1: { operation: 'host_action.host_action_v2_installer_v1', rollback: 'host-action-v2:host-action-v2-installer-v1:four-file-restore' },\n  imotion_marketing_target_register_v1: { operation: 'host_action.imotion_marketing_target_register_v1', rollback: 'host-action-v2:imotion-marketing-target-register-v1:source-restore' }\n});";
  return replaceOnce(s,a,b,'base_registry');
}
function patchExecutor(s){
  const a="  host_action_v2_installer_v1:{operation:'host_action.host_action_v2_installer_v1',kind:'host_action_v2_installer_v1'}\n});";
  const b="  host_action_v2_installer_v1:{operation:'host_action.host_action_v2_installer_v1',kind:'host_action_v2_installer_v1'},\n  imotion_marketing_target_register_v1:{operation:'host_action.imotion_marketing_target_register_v1',kind:'imotion_marketing_target_register_v1'}\n});";
  s=replaceOnce(s,a,b,'executor_registry');
  const anchor="const applyHostActionV2Original=applyHostActionV2;\n";
  const helper=`const IMOTION_MARKETING_TARGET_HELPER='${PATHS.helper}';\nconst IMOTION_MARKETING_TARGET_RESULT='/var/lib/prhm-agent-selfmaint-exec/imotion-marketing-target-register-v1/latest.json';\nfunction applyImotionMarketingTargetRegisterV1(){if(!fs.existsSync(IMOTION_MARKETING_TARGET_HELPER))throw new Error('imotion_marketing_target_helper_missing');try{if(fs.existsSync(IMOTION_MARKETING_TARGET_RESULT))fs.unlinkSync(IMOTION_MARKETING_TARGET_RESULT)}catch{};const u='prhm-imotion-marketing-target-register-v1-'+Date.now();const a=['--wait','--unit='+u,'--property=Type=oneshot','--property=UMask=0077','--property=NoNewPrivileges=true','--property=PrivateTmp=true','--property=ProtectSystem=strict','--property=ProtectHome=read-only','--property=ReadWritePaths=/home/agent/ssh-agent-api /home/agent/ssh-mcp-server /opt/prhm-agent-selfmaint-exec/actions /var/lib/prhm-agent-selfmaint-exec /var/backups/prhm-imotion-marketing-target-v1','--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',IMOTION_MARKETING_TARGET_HELPER];cp.execFileSync('/usr/bin/systemd-run',a,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:600000});const r=readJson(IMOTION_MARKETING_TARGET_RESULT);if(r.ok!==true||r.action!=='imotion_marketing_target_register_v1'||r.schema_version!=='prhm.host-action-result.v1'||r.target_root_exists!==true||r.wordpress_detected!==true||r.registered_in_source!==true||r.requires_zdt_refresh!==true||r.production_site_mutation!==false||r.database_mutation!==false||r.redirect_mutation!==false||r.canonical_mutation!==false||r.rollback_performed!==false)throw new Error('imotion_marketing_target_result_invalid');return r}\n`;
  s=replaceOnce(s,anchor,helper+anchor,'executor_helper');
  const dispatch="applyHostActionV2=async function(action){if(action==='host_action_v2_installer_v1')return applyHostActionV2InstallerV1();if(action==='agent_zero_downtime_bootstrap_v1')return applyAgentZeroDowntimeBootstrapV1();return applyHostActionV2Original(action);};";
  const next="applyHostActionV2=async function(action){if(action==='imotion_marketing_target_register_v1')return applyImotionMarketingTargetRegisterV1();if(action==='host_action_v2_installer_v1')return applyHostActionV2InstallerV1();if(action==='agent_zero_downtime_bootstrap_v1')return applyAgentZeroDowntimeBootstrapV1();return applyHostActionV2Original(action);};";
  return replaceOnce(s,dispatch,next,'executor_dispatch');
}
function patchPolicy(s){
  const d=JSON.parse(s);
  if(!d.operations||!Array.isArray(d.typed_scopes))fail('policy_shape_invalid');
  if(d.operations[OPERATION]||d.typed_scopes.some(x=>x&&x.action===ACTION))fail('policy_target_already_exists');
  d.operations[OPERATION]={level:4};
  d.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:OPERATION,principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});
  return JSON.stringify(d,null,2)+'\n';
}
function patchMcp(s){
  const a="'agent_zero_downtime_bootstrap_v1','host_action_v2_installer_v1']);";
  const b="'agent_zero_downtime_bootstrap_v1','host_action_v2_installer_v1','imotion_marketing_target_register_v1']);";
  return replaceOnce(s,a,b,'mcp_enum');
}
function replaceShaOnce(s,oldSha,newSha,label){if(!/^[a-f0-9]{64}$/.test(newSha))fail('new_sha_invalid:'+label);return replaceOnce(s,oldSha,newSha,'zdt_'+label)}
function patchZdt(s,hashes){
  s=replaceShaOnce(s,ZDT_OLD.mcp,hashes.mcp,'mcp');
  s=replaceShaOnce(s,ZDT_OLD.selfmaint,CURRENT_STATIC.selfmaint,'selfmaint');
  s=replaceShaOnce(s,ZDT_OLD.api,CURRENT_STATIC.api,'api');
  s=replaceShaOnce(s,ZDT_OLD.base,hashes.base,'base');
  s=replaceShaOnce(s,ZDT_OLD.executor,hashes.executor,'executor');
  return s;
}
function helperForZdt(zdtSha){
  const bytes=Buffer.from(HELPER_TEMPLATE_B64,'base64');
  if(sha(bytes)!==HELPER_TEMPLATE_SHA)fail('helper_template_sha_mismatch');
  const text=bytes.toString('utf8');
  const old=BASELINE.zdt;
  if(count(text,old)!==1)fail('helper_zdt_baseline_anchor_count:'+count(text,old));
  return Buffer.from(text.replace(old,zdtSha),'utf8');
}
function syntax(bytes,ext,label){const tmp='/tmp/prhm-imotion-v15-'+label+'-'+process.pid+'-'+Date.now()+ext;try{fs.writeFileSync(tmp,bytes,{flag:'wx',mode:0o600});const r=cp.spawnSync('/usr/local/bin/prhm-node',['--check',tmp],{encoding:'utf8',timeout:30000,maxBuffer:200000});if(r.error||r.status!==0)fail('syntax_failed:'+label+':'+String(r.stderr||r.stdout||r.error?.message||'').slice(-500));}finally{try{fs.unlinkSync(tmp)}catch{}}}
function verifyBaseline(){for(const k of ['base','executor','policy','mcp','zdt']){if(!fs.existsSync(PATHS[k])||!regular(PATHS[k]))fail('missing_or_unsafe:'+k);const a=shaFile(PATHS[k]);if(a!==BASELINE[k])fail('baseline_drift:'+k+':'+a)}if(fs.existsSync(PATHS.helper))fail('helper_target_already_exists');return true}
function build(){
  verifyBaseline();
  const base=Buffer.from(patchBase(fs.readFileSync(PATHS.base,'utf8')));
  const executor=Buffer.from(patchExecutor(fs.readFileSync(PATHS.executor,'utf8')));
  const policy=Buffer.from(patchPolicy(fs.readFileSync(PATHS.policy,'utf8')));
  const mcp=Buffer.from(patchMcp(fs.readFileSync(PATHS.mcp,'utf8')));
  const hashes={base:sha(base),executor:sha(executor),policy:sha(policy),mcp:sha(mcp)};
  const zdt=Buffer.from(patchZdt(fs.readFileSync(PATHS.zdt,'utf8'),hashes));hashes.zdt=sha(zdt);
  const helper=helperForZdt(hashes.zdt);hashes.helper=sha(helper);
  syntax(base,'.cjs','base');syntax(executor,'.cjs','executor');syntax(mcp,'.mjs','mcp');syntax(zdt,'.cjs','zdt');syntax(helper,'.cjs','helper');JSON.parse(policy.toString('utf8'));
  return{base,executor,policy,mcp,zdt,helper,hashes};
}
function atomic(file,bytes,mode){fs.mkdirSync(path.dirname(file),{recursive:true,mode:0o755});const tmp=file+'.v15-'+process.pid+'-'+Date.now()+'.tmp';let fd;try{fd=fs.openSync(tmp,'wx',mode);fs.writeFileSync(fd,bytes);fs.fsyncSync(fd);}finally{if(fd!==undefined)fs.closeSync(fd)}fs.renameSync(tmp,file);fs.chmodSync(file,mode)}
function backupOriginals(){const dir=path.join(BACKUP_ROOT,new Date().toISOString().replace(/[:.]/g,'-'));fs.mkdirSync(dir,{recursive:true,mode:0o700});const states={};for(const k of ['base','executor','policy','mcp','zdt']){const f=PATHS[k],st=fs.lstatSync(f),bak=path.join(dir,k+'.bak');fs.copyFileSync(f,bak,fs.constants.COPYFILE_EXCL);fs.chmodSync(bak,0o600);states[k]={file:f,backup:bak,mode:st.mode&0o777,sha256:shaFile(f)}}return{dir,states,helper_existed:false,phase:'prepared'}}
function restoreBackup(backup,mutated){const errors=[];for(const k of [...mutated].reverse()){try{if(k==='helper'){try{fs.unlinkSync(PATHS.helper)}catch(e){if(e.code!=='ENOENT')throw e};continue}const s=backup.states[k],b=fs.readFileSync(s.backup);if(sha(b)!==s.sha256)throw Error('backup_sha_mismatch');atomic(s.file,b,s.mode)}catch(e){errors.push(k+':'+e.message)}}if(errors.length)fail('rollback_restore_failed:'+errors.join('|'));return true}
function restartServices(){for(const unit of ['prhm-company-approval.service','prhm-agent-selfmaint.service','prhm-agent-selfmaint-exec.service','prhm-agent-mcp.service']){cp.execFileSync('/usr/bin/systemctl',['restart',unit],{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:90000});const a=cp.execFileSync('/usr/bin/systemctl',['is-active',unit],{encoding:'utf8',timeout:30000}).trim();if(a!=='active')fail('service_not_active:'+unit)}}
function resultBase(){return{ok:false,action:INSTALLER_ACTION,target_action:ACTION,schema_version:'prhm.host-action-bootstrap-result.v1',production_site_mutation:false,database_mutation:false,redirect_mutation:false,canonical_mutation:false,site_content_mutation:false,mcp_refresh_required:true,rollback:{performed:false}}}
function preflight(){const c=build();return{...resultBase(),ok:true,preflight_only:true,production_mutation:false,baseline_match:true,candidate_sha256:c.hashes,helper_template_sha256:HELPER_TEMPLATE_SHA,rollback:{performed:false}}}
function apply(){const out=resultBase(),c=build(),backup=backupOriginals(),mutated=[];let phase='prepared';try{for(const k of ['helper','base','executor','policy','mcp','zdt']){phase='write_'+k;mutated.push(k);atomic(PATHS[k],c[k],k==='helper'?0o750:backup.states[k].mode);if(shaFile(PATHS[k])!==c.hashes[k])fail('post_write_sha_mismatch:'+k)}phase='restart';restartServices();out.ok=true;out.installed=true;out.production_mutation=true;out.preflight_only=false;out.phase='complete';out.backup_dir=backup.dir;out.post_install_sha256=c.hashes;out.rollback={performed:false};fs.mkdirSync(path.dirname(RESULT),{recursive:true,mode:0o700});atomic(RESULT,Buffer.from(JSON.stringify(out,null,2)+'\n'),0o600);return out}catch(e){let rb=false;try{restoreBackup(backup,mutated);restartServices();rb=true}catch(rbe){throw new Error('install_failed_and_rollback_failed:'+String(e.message||e)+':'+String(rbe.message||rbe))}out.phase=phase;out.error=String(e.message||e).slice(0,1000);out.rollback={performed:rb};throw new Error('install_failed_rolled_back:'+out.error)}}
function main(){const args=process.argv.slice(2);if(args.length!==1||!['--preflight-only','--apply'].includes(args[0]))fail('unexpected_arguments');const r=args[0]==='--preflight-only'?preflight():apply();process.stdout.write(JSON.stringify(r)+'\n')}
module.exports={ACTION,OPERATION,INSTALLER_ACTION,BASELINE,PATHS,HELPER_TEMPLATE_SHA,patchBase,patchExecutor,patchPolicy,patchMcp,patchZdt,helperForZdt,restoreBackup,preflight,apply};
if(require.main===module){try{main()}catch(e){process.stderr.write(String(e.stack||e)+'\n');process.exit(1)}}
